'use client'

import Link from 'next/link'
import Image from 'next/image'
import { useTranslations } from 'next-intl'
import { motion } from 'framer-motion'

interface MenuCategoriesProps {
  locale: string
  categoryImages: Record<string, string>
}

import { DEFAULT_IMAGES as SHARED_DEFAULTS } from '@/lib/default-images'
import { FEATURES } from '@/lib/nav'

// Short-key view over the shared fallback map
const DEFAULT_IMAGES = {
  body: SHARED_DEFAULTS.category_body_treatments,
  facial: SHARED_DEFAULTS.category_facial_treatments,
  packages: SHARED_DEFAULTS.category_packages,
  membership: SHARED_DEFAULTS.category_membership,
  giftcards: SHARED_DEFAULTS.category_giftcards,
  promotions: SHARED_DEFAULTS.category_promotions,
}

export function MenuCategories({ locale, categoryImages }: MenuCategoriesProps) {
  // Build categories with images from database (falling back to defaults)
  const categories = [
    {
      id: 'body',
      titleKey: 'body',
      image: categoryImages.category_body_treatments || DEFAULT_IMAGES.body,
      href: '/menu/corporales',
    },
    {
      id: 'facial',
      titleKey: 'facial',
      image: categoryImages.category_facial_treatments || DEFAULT_IMAGES.facial,
      href: '/menu/faciales',
    },
    ...(FEATURES.parejas
      ? [
          {
            id: 'couples',
            titleKey: 'couples',
            image: categoryImages.category_parejas || SHARED_DEFAULTS.category_parejas,
            href: '/parejas',
          },
        ]
      : []),
    {
      id: 'packages',
      titleKey: 'packages',
      image: categoryImages.category_packages || DEFAULT_IMAGES.packages,
      href: '/menu/paquetes',
    },
    {
      id: 'membership',
      titleKey: 'membership',
      image: categoryImages.category_membership || DEFAULT_IMAGES.membership,
      href: '/menu/membresia',
    },
    {
      id: 'giftcards',
      titleKey: 'giftcards',
      image: categoryImages.category_giftcards || DEFAULT_IMAGES.giftcards,
      href: '/menu/giftcards',
    },
    {
      id: 'promotions',
      titleKey: 'promotions',
      image: categoryImages.category_promotions || DEFAULT_IMAGES.promotions,
      href: '/promociones',
      special: true,
    },
  ]
  const t = useTranslations('menu.categories')
  const tNav = useTranslations('navigation')
  const tExtra = useTranslations('menu.categoriesExtra')
  const tCommon = useTranslations('common')

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
      {categories.map((category, index) => (
        <motion.div
          key={category.id}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: index * 0.1 }}
        >
          <Link
            href={`/${locale}${category.href}`}
            className="group block relative aspect-[4/3] rounded-lg overflow-hidden"
          >
            {/* Image */}
            <Image
              src={category.image}
              alt={category.special ? tNav('promotions') : t(category.titleKey)}
              fill
              className="object-cover transition-transform duration-700 group-hover:scale-110"
              sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
            />

            {/* Overlay */}
            <div className="absolute inset-0 bg-dark/40 group-hover:bg-dark/50 transition-colors" />

            {/* Content */}
            <div className="absolute inset-0 flex flex-col items-center justify-center text-white p-6">
              {category.special && (
                <span className="text-sm font-light italic mb-2 text-gold-100">
                  {tExtra('promotionsTagline')}
                </span>
              )}
              <h3 className="text-xl md:text-2xl font-display font-semibold text-center mb-4 tracking-wide">
                {category.special ? tExtra('promotionsTitle') : t(category.titleKey).toUpperCase()}
              </h3>
              <span className="inline-flex items-center px-6 py-2 bg-warm-gray-500/80 hover:bg-gold hover:text-dark rounded text-sm font-medium transition-all">
                {tCommon('view').toUpperCase()}
              </span>
            </div>
          </Link>
        </motion.div>
      ))}
    </div>
  )
}
